289 */
290 private Payment createGeneralPayment(Order order, User user, GeneralPaymentRequestDto requestDto) {
291 Instant start = Instant.now();
292 try {
293 log.info("일반 결제 처리 시작: 주문ID={}, impUid={}",
294 order.getId(), requestDto.getImpUid());
295
296 // 필수 데이터 검증
297 if (requestDto.getImpUid() == null || requestDto.getImpUid().isBlank()) {
298 throw new PaymentException(PaymentErrorCode.PAYMENT_VALIDATION_FAILED,
299 "결제 ID(impUid)는 필수 항목입니다.");
300 }
301
302 GeneralPayment generalPayment = GeneralPayment.builder()
303 .impUid(requestDto.getImpUid())
304 .pgProvider(requestDto.getPgProvider())
305 .receiptUrl(requestDto.getReceiptUrl())
306 .buyerName(requestDto.getBuyerName())
307 .buyerEmail(requestDto.getBuyerEmail())
308 .paidAmount(requestDto.getPaidAmount())
309 .build();
310
311 generalPayment.assignOrder(order);
312 generalPayment.assignUser(user);
313 generalPayment.updateSuccessStatus(true);
314 generalPayment.updateStatus(PaymentStatus.PAID);
315
316 GeneralPayment savedPayment = (GeneralPayment) paymentRepository.save(generalPayment);
317 log.info("일반 결제 처리 완료: 주문ID={}, 결제ID={}, 상태={}",
318 order.getId(), savedPayment.getId(), savedPayment.getStatus());
319
320 // 처리 시간 로깅
321 Instant end = Instant.now();
322 Duration duration = Duration.between(start, end);
323 log.debug("일반 결제 처리 시간: {}ms", duration.toMillis());
324
325 return savedPayment;
326 } catch (PaymentException e) {
327 throw e; // 이미 PaymentException이면 그대로 전파
328 } catch (Exception e) {
329 log.error("일반 결제 처리 중 예상치 못한 오류 발생: 주문ID={}, 오류={}",
330 order.getId(), e.getMessage(), e);
331 throw new PaymentProcessingException("일반 결제 처리 중 오류가 발생했습니다: " + e.getMessage());
332 }
333 }
